/// <summary>
/// VendInvoiceInfoLine table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoLine))]
final class METVendInvoiceInfoLine_Extension
{
    

}

Method.Source:
    /// <summary>
    /// FieldId modified logic
    /// </summary>
    /// <param name = "_fieldId">FieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        switch(_fieldId)
        {
            case fieldNum(VendInvoiceInfoLine, ReceiveNow):
            case fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow):           
            case fieldNum(VendInvoiceInfoLine, PurchPrice):
                if(!this.isNonPO())
                {
                    this.metFetchInitializeReasonCode(_fieldId == fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow) || 
                                                    this.PdsCWReceiveNow);
                }
                break;
            case fieldNum(VendInvoiceInfoLine, ReasonTableRef):
                ReasonTableRef  metReasonTableRef  = ReasonTableRef::find(this.ReasonTableRef);
     
                this.metInitReasonCode(metReasonTableRef.Reason, metReasonTableRef ? true : false);
                break;

            case fieldNum(VendInvoiceInfoLine, TaxItemGroup):
                this.metUpdateMarkupTransTaxItemGroup();
                break;
        }
    }

    /// <summary>
    /// Update TaxItemGroup
    /// </summary>
    public void metUpdateMarkupTransTaxItemGroup()
    {
        MarkupTrans         markupTrans;
        MarkupTable         markupTable;

        update_recordset markupTrans
            setting TaxItemGroup = this.TaxItemGroup
            exists join markupTable
            where markupTable.MarkupCode    == markupTrans.MarkupCode
            && markupTable.TaxItemGroup     == ''
            && markupTrans.TransTableId     == tableNum(VendInvoiceInfoLine)
            && markupTrans.TransRecId       == this.RecId
            && markupTrans.TaxItemGroup     != this.TaxItemGroup;
    }

    /// <summary>
    /// Edit method for reason code
    /// </summary>
    /// <param name = "_set">booelan</param>
    /// <param name = "_reasonCode">reasoncode</param>
    /// <returns>ReasonCode</returns>
    public edit ReasonCode editReasonCode(boolean _set, ReasonCode _reasonCode)
    {
        ReasonCode metReasonCode = next editReasonCode(_set, _reasonCode);

        if(_set)
        {
            this.modifiedField(fieldNum(VendInvoiceInfoLine, ReasonTableRef));
        }

        return metReasonCode;
    }

    /// <summary>
    /// Initialise reasoncode
    /// </summary>
    /// <param name = "_useCatchWeight">True to use catchWeight; else false</param>
    private void metFetchInitializeReasonCode(boolean _useCatchWeight)
    {
        boolean qtyVariance, priceVariance;
        Query   query;

        if(this.checkIfQuantityMatch() == LastMatchVarianceOptions::Warning &&
           (this.ReceiveNow > this.purchQtyMatched() || this.PdsCWReceiveNow > this.pdsCWQtyMatched()))
        {
            qtyVariance = true;
        }

        if(this.priceVarianceStatus() == LastMatchVarianceOptions::Warning)
        {
            priceVariance = true;
        }

        query = this.metInvoiceMatchingReasonQuery(priceVariance, qtyVariance, _useCatchWeight);

        if(query)
        {
            QueryRun queryRun = new QueryRun(query);

            if(queryRun.next())
            {
                ReasonTable reason = queryRun.get(tableNum(ReasonTable));
                this.metInitReasonCode(reason.Reason);
            }
        }
        else
        {
            this.metInitReasonCode('');
        }
    }

    /// <summary>
    /// Update query
    /// </summary>
    /// <param name = "_priceVariance">true if price variance; else false</param>
    /// <param name = "_qtyVariance">true if qty variance; else false</param>
    /// <param name = "_isCatchWeight">true if catch weight; else false</param>
    /// <param name = "_skipMultipleCheck">true if multiple check; else false</param>
    /// <returns>Updated query</returns>
    public Query metInvoiceMatchingReasonQuery(boolean _priceVariance, boolean _qtyVariance, 
                                               boolean _isCatchWeight = false, boolean _skipMultipleCheck = false)
    {
        Query                   query;
        QueryBuildDataSource    qbdsReasonTable;

        if(_priceVariance || _qtyVariance)
        {
            query = new Query();
            qbdsReasonTable = query.addDataSource(tableNum(ReasonTable));
            qbdsReasonTable.firstOnly(true);

            qbdsReasonTable.addRange(fieldNum(ReasonTable, Vend)).value(queryValue(NoYes::Yes));
            qbdsReasonTable.addRange(fieldNum(ReasonTable, METInvoiceMatch)).value(queryValue(NoYes::Yes));
            qbdsReasonTable.addRange(fieldNum(ReasonTable, METApprove)).value(queryValue(NoYes::No));

            if(_qtyVariance && _priceVariance && !_skipMultipleCheck)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METPriceVar)).value(queryValue(NoYes::Yes));

                if(_isCatchWeight)
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METRWQty)).value(queryValue(NoYes::Yes));
                }
                else
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METQtyVar)).value(queryValue(NoYes::Yes));
                }
            }
            else if(_qtyVariance)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METOver)).value(queryValue(NoYes::Yes));

                if(_isCatchWeight)
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METRWQty)).value(queryValue(NoYes::Yes));
                }
                else
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METQtyVar)).value(queryValue(NoYes::Yes));
                }
            }
            else if(_priceVariance)
            {
                qbdsReasonTable.addRange(fieldNum(ReasonTable, METPriceVar)).value(queryValue(NoYes::Yes));

                if(this.priceVariancePercent() > 0)
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METOver)).value(queryValue(NoYes::Yes));
                }
                else
                {
                    qbdsReasonTable.addRange(fieldNum(ReasonTable, METUnder)).value(queryValue(NoYes::Yes));
                }
            }
        }

        return query; 
    }

   /// <summary>
   /// Initialise or create reasoncode
   /// </summary>
   /// <param name = "_reasonCode">ReasonCode</param>
   /// <param name = "_create">true if new record to be created; otherwise false</param>
    private void metInitReasonCode(ReasonCode _reasonCode, boolean _create = true)
    {
        ReasonTable reasonTable = ReasonTable::find(_reasonCode);

        if(reasonTable && _create)
        {
            this.ReasonTableRef = ReasonTableRef::createReasonTableRef(reasonTable.Reason, reasonTable.Description);
        }
        else
        {
            this.ReasonTableRef = 0;
        }

        this.MetAutoApprove = reasonTable.METApprove;
        this.MetClaimLine   = reasonTable.METClaim;
        this.MetExtComment  = reasonTable.MetExtComment;
        this.MetMultiple    = reasonTable.MetMultiple;
    }

    /// <summary>
    /// Initialise VendInvoiceInfoLine, price variance line
    /// </summary>
    /// <param name = "_vendInvoiceInfoLine">VendInvoiceInfoLine</param>
    /// <param name = "_reasonTable">ReasonTable</param>
    /// <param name = "_isQtyFailure">True if Qty failure; otherwise false</param>
    /// <param name = "_isCatchWeight">True if Qty failure; otherwise false</param>
    public void metInitPriceFailureMatchingLine(VendInvoiceInfoLine _vendInvoiceInfoLine, ReasonTable _reasonTable, 
                                             boolean _isQtyFailure, boolean _isCatchWeight)
    {
        PurchLine               purchLine               = _vendInvoiceInfoLine.purchLine();
        InventTable             inventTable             = this.inventTable();
        InventQty               toReceiveNowInvent;
        int                     factor;

        this.clear();
        this.initValue();

        this.ParmId                 = _vendInvoiceInfoLine.ParmId;
        this.TableRefId             = _vendInvoiceInfoLine.TableRefId;
        this.currencyCode           = _vendInvoiceInfoLine.currencyCode;
        this.AddressRefRecId        = _vendInvoiceInfoLine.AddressRefRecId;
        this.AddressRefTableId      = _vendInvoiceInfoLine.AddressRefTableId;
        this.DeliveryName           = _vendInvoiceInfoLine.DeliveryName;
        this.DeliveryPostalAddress  = _vendInvoiceInfoLine.DeliveryPostalAddress;
        this.MetTransRefId          = _vendInvoiceInfoLine.RecId;
        this.TaxGroup               = _vendInvoiceInfoLine.TaxGroup;
        this.TaxItemGroup           = _vendInvoiceInfoLine.TaxItemGroup;
        this.DefaultDimension       = _vendInvoiceInfoLine.DefaultDimension;
        this.InventDimId            = _vendInvoiceInfoLine.InventDimId;

        this.ItemId                 = _reasonTable.METItem;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));

        this.MetClaimLine           = _reasonTable.METClaim;
        this.MetAutoApprove         = _reasonTable.METApprove;
        this.MetExtComment          = _reasonTable.MetExtComment;

        this.ReasonTableRef         = ReasonTableRef::createReasonTableRef(_reasonTable.Reason, _reasonTable.Description);
        this.Description            = strFmt("@MET:PlaceHolder", _vendInvoiceInfoLine.VendDocumentLineMap::name(), _reasonTable.MetExtComment);

        this.PurchPrice = _isQtyFailure ? _vendInvoiceInfoLine.PurchPrice :
                                          abs(_vendInvoiceInfoLine.PurchPrice - purchLine.PurchPrice);
        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        if(_isQtyFailure)
        {
            if(!_isCatchWeight)
            {
                this.ReceiveNow = _vendInvoiceInfoLine.ReceiveNow - _vendInvoiceInfoLine.purchQtyMatched();
            }
            else
            {
                this.PdsCWReceiveNow    = _vendInvoiceInfoLine.PdsCWReceiveNow - _vendInvoiceInfoLine.pdsCWQtyMatched();
                toReceiveNowInvent      = PdsCatchWeight::inventQty(inventTable.ItemId, this.PdsCWReceiveNow);

                this.ReceiveNow         = EcoResProductUnitConverter::convertForReleasedProduct(
                                            inventTable.ItemId,
                                            this.InventDimId,
                                            toReceiveNowInvent,
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTable.inventUnitId()),
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.purchLine().PurchUnit),
                                            NoYes::Yes,
                                            NoYes::No);

            }

        }
        else
        {
            factor = _vendInvoiceInfoLine.PurchPrice > purchLine.PurchPrice ? 1 : -1;

            if(!_isCatchWeight)
            {
                this.ReceiveNow = _vendInvoiceInfoLine.purchQtyMatched() * factor;
            }
            else
            {
                this.PdsCWReceiveNow    = _vendInvoiceInfoLine.pdsCWQtyMatched() * factor;
                toReceiveNowInvent      = PdsCatchWeight::inventQty(inventTable.ItemId, this.PdsCWReceiveNow);

                this.ReceiveNow = EcoResProductUnitConverter::convertForReleasedProduct(
                                            inventTable.ItemId,
                                            this.InventDimId,
                                            toReceiveNowInvent,
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(inventTable.inventUnitId()),
                                            EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(this.purchLine().PurchUnit),
                                            NoYes::Yes,
                                            NoYes::No);
            }
        }

        this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(_isCatchWeight, UnknownNoYes::Yes);
    }

    /// <summary>
    /// Reset receipted invoice line
    /// </summary>
    public void metResetReceiptedInvoiceLine()
    {
        boolean                 useCatchWeight          = this.PdsCWReceiveNow ? true : false;

        this.PurchPrice         = this.purchLine().PurchPrice;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        this.PdsCWReceiveNow    = this.pdsCWQtyMatched();
        this.ReceiveNow         = this.purchQtyMatched();

        this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(useCatchWeight, UnknownNoYes::Yes);
        this.modifiedField(fieldNum(VendInvoiceInfoLine, ReceiveNow));

        if(this.validateWrite())
        {
            this.update();
        }
    }
